    const current = this.drawer; this.drawer = null; this.pickerField = null; this.error = '';
    if (current === 'model') { this.showModelForm = false; this.cancelModelEdit(); }
    if (current === 'editKey') { this.keyEditVersion++; this.editingKey = null; }
    if (current === 'group') { this.groupEditVersion++; this.groupEditing = null; this.groupError = ''; }
    if (current === 'provider' || current === 'providerKey') { this.providerKey = ''; this.rotateSecret = ''; }
    if (current === 'issueKey') this.issuedKey = '';
    if (current === 'admin') this.newPassword = '';
    const origin = this.drawerOrigin; this.drawerOrigin = null;
