    if (start && end && start >= end) { this.error = '종료 시간은 시작 시간보다 늦어야 합니다.'; return; }
    if (this.error === '조회 시간을 YYYY-MM-DD:HHmm 형식의 유효한 현지 시간으로 입력하세요.' || this.error === '종료 시간은 시작 시간보다 늦어야 합니다.') this.error = '';
