    if (this.usageModel !== null) metricParams = metricParams.set('model_id', this.usageModel);
    if (this.usageKey !== null) metricParams = metricParams.set('key_id', this.usageKey);
    if (this.usageOperation) metricParams = metricParams.set('operation', this.usageOperation);
    if (this.usageStatus) metricParams = metricParams.set('status', this.usageStatus);
    this.http.get<Metrics>('/admin/metrics', {headers: this.headers(), params: metricParams}).subscribe({next: data => {if (usageVersion === this.usageListVersion) this.update(() => this.metrics = data);}, error: () => {if (usageVersion === this.usageListVersion) this.update(() => this.observationError = true);}});
    this.http.get<UsageSummary[]>('/admin/usage', {headers: this.headers(), params}).subscribe({next: data => {if (usageVersion === this.usageListVersion) this.update(() => {this.usage = data; this.usageSummaryLoading = false;});}, error: () => {if (usageVersion === this.usageListVersion) this.update(() => {this.usageSummaryLoading = false; this.observationError = true;});}});
    this.requestListParams = this.requestRoot.trim() ? params.set('root_request_id', this.requestRoot.trim()) : params;
    this.http.get<UsageRequest[]>('/admin/usage/requests', {headers: this.headers(), params:this.requestListParams}).subscribe({next: data => {if (usageVersion === this.usageListVersion) this.update(() => {this.usageRequests = data; this.usageHasMore = data.length === 100;});}, error: () => {if (usageVersion === this.usageListVersion) this.update(() => this.observationError = true);}});
